import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { FlatCompat } from "@eslint/eslintrc";

const compat = new FlatCompat({ baseDirectory: dirname(fileURLToPath(import.meta.url)) });

const config = [
  // next-env.d.ts is generated by Next on every build and is not ours to lint.
  { ignores: [".next/**", "node_modules/**", "next-env.d.ts"] },
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    rules: {
      /**
       * Reading a `let` or `const` above its declaration.
       *
       * TypeScript does not catch this across a function boundary: a helper
       * defined above the variables it writes typechecks perfectly and throws
       * at runtime, because a `let` is in its temporal dead zone until its
       * declaration runs. NN shipped exactly that into the Applications view
       * — the carousel's theme reader ran before the two variables it set
       * were declared, the effect threw on mount, and React replaced the
       * whole screen with an error page. Unit tests could not see it: jsdom
       * has no WebGL, so the path never ran.
       *
       * Functions are exempt, because hoisting them is how a file is read
       * top-down: the entry points first, the helpers under them.
       */
      "no-use-before-define": ["error", { functions: false, classes: true, variables: true }],
    },
  },
];

export default config;
